// Generated by Local AI (qwen2.5-coder:7b) — Refined with Guest Quota, Scan Reference & Severe-Case Escalation
package com.kelompok4.oralhealthplus.feature.chatbot

import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import androidx.lifecycle.viewModelScope
import com.kelompok4.oralhealthplus.BuildConfig
import com.kelompok4.oralhealthplus.data.local.SessionManager
import com.kelompok4.oralhealthplus.data.local.dao.ChatMessageDao
import com.kelompok4.oralhealthplus.data.local.entity.ChatMessageEntity
import com.kelompok4.oralhealthplus.data.local.entity.DetectionHistoryEntity
import com.kelompok4.oralhealthplus.data.remote.GeminiApiClient
import com.kelompok4.oralhealthplus.data.repository.HistoryRepository
import com.kelompok4.oralhealthplus.feature.auth.GuestAccessPolicy
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.flatMapLatest
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

data class ChatbotUiState(
    val isSending: Boolean = false,
    val errorMessage: String? = null,
    val securityWarning: String? = null,
    val isSuspended: Boolean = false,
    val suspensionMessage: String? = null,
    val quickPrompts: List<String> = emptyList(),
    val isGuest: Boolean = true,
    val remainingGuestQuestions: Int = GuestAccessPolicy.MAX_GUEST_CHAT_QUESTIONS,
    val isGuestChatLimitReached: Boolean = false,
    val isSevereCaseDetected: Boolean = false,
    val severeCaseReason: String? = null,
    val hasCustomSelectedDetection: Boolean = false
)

@OptIn(ExperimentalCoroutinesApi::class)
class ChatbotViewModel(
    private val historyRepository: HistoryRepository,
    private val chatMessageDao: ChatMessageDao,
    private val sessionManager: SessionManager,
    private val geminiApiClient: GeminiApiClient = GeminiApiClient()
) : ViewModel() {

    private val currentUsername: String get() = sessionManager.getLoggedInUsername() ?: "guest"

    private val selectedDetectionOverride = MutableStateFlow<DetectionHistoryEntity?>(null)

    val messages: StateFlow<List<ChatMessageEntity>> = sessionManager.loggedInUsernameFlow
        .flatMapLatest { username ->
            chatMessageDao.observeMessagesForUser(username ?: "guest")
        }
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), emptyList())

    val latestDetection: StateFlow<DetectionHistoryEntity?> = combine(
        selectedDetectionOverride,
        historyRepository.observeLatestDetection()
    ) { selected, latest ->
        selected ?: latest
    }.stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), null)

    private val _uiState = MutableStateFlow(
        ChatbotUiState(
            quickPrompts = ContextualPromptBuilder.defaultQuickPrompts(null),
            isGuest = !sessionManager.isLoggedIn(),
            remainingGuestQuestions = sessionManager.getGuestQuotaState().remainingGuestChats,
            isGuestChatLimitReached = !sessionManager.getGuestQuotaState().canAskChatbot
        )
    )
    val uiState: StateFlow<ChatbotUiState> = _uiState.asStateFlow()

    init {
        refreshSuspensionStatus()

        viewModelScope.launch {
            latestDetection.collect { detection ->
                val isHighUrgency = detection?.urgensi.equals("SEGERA_KE_DOKTER", ignoreCase = true)
                _uiState.update { state ->
                    state.copy(
                        quickPrompts = ContextualPromptBuilder.defaultQuickPrompts(detection),
                        hasCustomSelectedDetection = selectedDetectionOverride.value != null,
                        isSevereCaseDetected = if (isHighUrgency) true else state.isSevereCaseDetected,
                        severeCaseReason = if (isHighUrgency && detection != null) {
                            val nama = detection.kelas.replace("_", " ")
                            "Hasil scan mulut Anda ($nama) menunjukkan tingkat urgensi tinggi (Segera ke Dokter). Segera hubungi dokter gigi atau kunjungi klinik terdekat."
                        } else {
                            state.severeCaseReason
                        }
                    )
                }
            }
        }

        viewModelScope.launch {
            combine(
                sessionManager.loggedInUsernameFlow,
                sessionManager.guestChatCountFlow
            ) { loggedInUser, chatCount ->
                val isLoggedIn = loggedInUser != null
                val remaining = if (isLoggedIn) {
                    Int.MAX_VALUE
                } else {
                    (GuestAccessPolicy.MAX_GUEST_CHAT_QUESTIONS - chatCount).coerceAtLeast(0)
                }
                Triple(!isLoggedIn, remaining, !isLoggedIn && remaining <= 0)
            }.collect { (isGuest, remaining, limitReached) ->
                _uiState.update {
                    it.copy(
                        isGuest = isGuest,
                        remainingGuestQuestions = remaining,
                        isGuestChatLimitReached = limitReached
                    )
                }
                refreshSuspensionStatus()
            }
        }
    }

    /** Memilih riwayat deteksi tertentu sebagai referensi aktif Chatbot. */
    fun selectDetectionReference(detection: DetectionHistoryEntity) {
        selectedDetectionOverride.value = detection
        val isHighUrgency = detection.urgensi.equals("SEGERA_KE_DOKTER", ignoreCase = true)
        _uiState.update { state ->
            state.copy(
                hasCustomSelectedDetection = true,
                quickPrompts = ContextualPromptBuilder.defaultQuickPrompts(detection),
                isSevereCaseDetected = if (isHighUrgency) true else state.isSevereCaseDetected,
                severeCaseReason = if (isHighUrgency) {
                    val nama = detection.kelas.replace("_", " ")
                    "Referensi scan ($nama) berurgensi tinggi. Segera hubungi dokter gigi atau kunjungi klinik terdekat."
                } else {
                    state.severeCaseReason
                }
            )
        }
    }

    /** Kembali menggunakan hasil scan terbaru dari database sebagai referensi Chatbot. */
    fun useLatestDetectionReference() {
        selectedDetectionOverride.value = null
        _uiState.update { it.copy(hasCustomSelectedDetection = false) }
    }

    fun dismissSevereCaseAlert() {
        _uiState.update { it.copy(isSevereCaseDetected = false) }
    }

    fun refreshSuspensionStatus() {
        if (!ChatbotSecurityGate.ENABLE_SUSPENSION_BLOCKING) {
            _uiState.update {
                it.copy(
                    isSuspended = false,
                    suspensionMessage = null
                )
            }
            return
        }
        val user = currentUsername
        val state = sessionManager.getSecurityGateState(user)
        val now = System.currentTimeMillis()
        if (state.suspensionUntil > now) {
            val remaining = state.suspensionUntil - now
            val isPermanent = state.suspensionUntil == Long.MAX_VALUE
            val timeStr = ChatbotSecurityGate.formatRemainingTime(remaining, isPermanent)
            val msg = if (isPermanent) {
                "Akses Chatbot telah diblokir secara permanen pada perangkat ini karena pelanggaran berulang terhadap aturan penggunaan aplikasi."
            } else {
                "Akses Chatbot ditangguhkan sementara selama $timeStr karena pelanggaran aturan topik di luar kesehatan gigi & mulut."
            }
            _uiState.update {
                it.copy(
                    isSuspended = true,
                    suspensionMessage = msg
                )
            }
        } else {
            _uiState.update {
                it.copy(
                    isSuspended = false,
                    suspensionMessage = null
                )
            }
        }
    }

    fun sendMessage(rawInput: String) {
        val trimmed = rawInput.trim().take(1000)
        if (trimmed.isEmpty() || _uiState.value.isSending) return

        // 0. Cek kuota tamu (maksimal 3 pertanyaan sebelum login)
        val quota = sessionManager.getGuestQuotaState()
        if (!quota.canAskChatbot) {
            _uiState.update {
                it.copy(
                    isGuest = true,
                    remainingGuestQuestions = 0,
                    isGuestChatLimitReached = true
                )
            }
            return
        }

        val user = currentUsername
        val now = System.currentTimeMillis()
        val currentState = sessionManager.getSecurityGateState(user)

        // 1. Pre-Check Security Gate (Domain Relevance, Rate-Limit, Suspension)
        when (val evalResult = ChatbotSecurityGate.evaluateMessage(trimmed, now, currentState)) {
            is SecurityEvaluationResult.Blocked -> {
                _uiState.update {
                    it.copy(
                        isSuspended = true,
                        suspensionMessage = evalResult.message,
                        securityWarning = null
                    )
                }
                return
            }
            is SecurityEvaluationResult.SuspendedNow -> {
                sessionManager.saveSecurityGateState(user, evalResult.updatedState)
                _uiState.update {
                    it.copy(
                        isSuspended = true,
                        suspensionMessage = evalResult.message,
                        securityWarning = null
                    )
                }
                return
            }
            is SecurityEvaluationResult.RejectedSpam -> {
                _uiState.update {
                    it.copy(securityWarning = evalResult.message)
                }
                return
            }
            is SecurityEvaluationResult.RejectedOutOfScope -> {
                sessionManager.saveSecurityGateState(user, evalResult.updatedState)
                _uiState.update {
                    it.copy(securityWarning = evalResult.warningMessage)
                }
                return
            }
            is SecurityEvaluationResult.Allowed -> {
                sessionManager.saveSecurityGateState(user, evalResult.updatedState)
                _uiState.update {
                    it.copy(securityWarning = null, isSuspended = false, suspensionMessage = null)
                }
            }
        }

        // 2. Cek ketersediaan API key
        val apiKey = BuildConfig.GEMINI_API_KEY.trim()
        if (apiKey.isBlank()) {
            _uiState.update { it.copy(errorMessage = "Layanan konsultasi AI belum tersedia saat ini. Silakan coba lagi nanti.") }
            return
        }

        viewModelScope.launch {
            _uiState.update { it.copy(isSending = true, errorMessage = null, securityWarning = null) }
            val activeReference = selectedDetectionOverride.value ?: historyRepository.getLatestDetection()
            val recentMessages = withContext(Dispatchers.IO) { chatMessageDao.getMessagesForUser(user).takeLast(8) }

            val promptPayload = ContextualPromptBuilder.build(
                latestDetection = activeReference,
                userQuestion = trimmed,
                isFirstTurn = recentMessages.isEmpty()
            )

            // Deteksi kasus berat secara adaptif dari keluhan / hasil scan
            if (promptPayload.severityAssessment.severity == CaseSeverity.SEVERE_URGENT) {
                _uiState.update {
                    it.copy(
                        isSevereCaseDetected = true,
                        severeCaseReason = promptPayload.severityAssessment.reasonSummary
                    )
                }
            }

            withContext(Dispatchers.IO) {
                chatMessageDao.insertMessage(
                    ChatMessageEntity(
                        username = user,
                        message = trimmed,
                        isFromUser = true,
                        contextKelas = activeReference?.kelas
                    )
                )
            }

            val result = geminiApiClient.generateReply(
                apiKey = apiKey,
                systemInstruction = promptPayload.systemInstruction,
                conversationHistory = recentMessages,
                userMessage = promptPayload.wrappedUserMessage
            )
            result.onSuccess { reply ->
                withContext(Dispatchers.IO) {
                    chatMessageDao.insertMessage(
                        ChatMessageEntity(
                            username = user,
                            message = reply,
                            isFromUser = false,
                            contextKelas = activeReference?.kelas
                        )
                    )
                }
                if (!sessionManager.isLoggedIn()) {
                    sessionManager.recordGuestChatQuestion()
                }
                val urgentFromReply = ContextualPromptBuilder.isUrgentReplyContent(reply)
                _uiState.update { state ->
                    state.copy(
                        isSending = false,
                        errorMessage = null,
                        isSevereCaseDetected = state.isSevereCaseDetected || urgentFromReply,
                        severeCaseReason = state.severeCaseReason ?: if (urgentFromReply) {
                            "Asisten AI menyarankan pemeriksaan langsung segera. Hubungi dokter gigi atau cari klinik terdekat."
                        } else {
                            null
                        }
                    )
                }
            }.onFailure { err ->
                _uiState.update { it.copy(isSending = false, errorMessage = err.message ?: "Gagal terhubung ke Google Gemini API") }
            }
        }
    }

    fun clearChatHistory() {
        viewModelScope.launch(Dispatchers.IO) {
            chatMessageDao.clearMessagesForUser(currentUsername)
        }
        _uiState.update { it.copy(isSevereCaseDetected = false, severeCaseReason = null) }
    }

    fun clearError() { _uiState.update { it.copy(errorMessage = null) } }

    fun clearSecurityWarning() { _uiState.update { it.copy(securityWarning = null) } }

    class Factory(
        private val historyRepository: HistoryRepository,
        private val chatMessageDao: ChatMessageDao,
        private val sessionManager: SessionManager
    ) : ViewModelProvider.Factory {
        @Suppress("UNCHECKED_CAST")
        override fun <T : ViewModel> create(modelClass: Class<T>): T =
            ChatbotViewModel(historyRepository, chatMessageDao, sessionManager) as T
    }
}
